CREATE PROCEDURE FabDeliverySP (@OrdId int,@Coycode int,@GodId int,@FabDelID int)
AS
SELECT Mas_Fabric.Fabdesc, Mas_Color.ColorDesc, Mas_Count.CountName, StockTable.LotNo,StockTable.Gsm, StockTable.ll, StockTable.GG,Mas_Dia.Dia, ISNULL(sum(CurrentStock.Bg),0) as SB, ISNULL(sum(CurrentStock.Kg),0) as SK, ISNULL(sum(CurrentStock.Mt),0) as SM, CurrentStock.StockID, Mas_Uom.Uom,CurrentStock.OrdId,StockTable.FinGsm,Mas_Dia_1.Dia as FinDia,Isnull(StockTable.Print_DesignId,0) as DesignId,IsNull(Mas_Design.DesignDesc,'') as DesignDesc ,styleno FROM CurrentStock INNER JOIN      StockTable ON CurrentStock.StockID = StockTable.StockID INNER JOIN Mas_Fabric ON StockTable.FabID = Mas_Fabric.FabID INNER JOIN Mas_Count ON StockTable.CntID = Mas_Count.CountID INNER JOIN Mas_Dia ON StockTable.DiaID = Mas_Dia.DiaID LEFT OUTER JOIN Mas_Dia as Mas_Dia_1 ON StockTable.FinDiaID = Mas_Dia_1.DiaID INNER JOIN Mas_Uom ON Mas_Fabric.PriUomID = Mas_Uom.UomID LEFT OUTER JOIN Mas_Color ON StockTable.ColID = Mas_Color.ColID LEFT OUTER JOIN Mas_Design ON StockTable.Print_DesignId = Mas_Design.DesignID WHERE CurrentStock.OrdId = @Ordid and stocktable.coycode = @Coycode and CurrentStock.GodID=@GodId group by Mas_Fabric.Fabdesc, Mas_Color.ColorDesc, Mas_Count.CountName, StockTable.Gsm, StockTable.ll, StockTable.GG,Mas_Dia.Dia, CurrentStock.StockID, Mas_Uom.Uom,CurrentStock.OrdId,StockTable.FinGsm,Mas_Dia_1.Dia ,Isnull(StockTable.Print_DesignId,0) ,IsNull(Mas_Design.DesignDesc,'')  ,styleno,StockTable.LotNo having  ISNULL(sum(CurrentStock.Kg),0)>0 or ISNULL(sum(CurrentStock.Mt),0)>0 union all SELECT Mas_Fabric.Fabdesc, Mas_Color.ColorDesc, Mas_Count.CountName,StockTable.LotNo, StockTable.Gsm, StockTable.ll, StockTable.GG,Mas_Dia.Dia, 0 as SB, 0 as SK, 0 as SM, trs_del2.StockID, Mas_Uom.Uom,trs_del2.OrdId,StockTable.FinGsm,Mas_Dia_1.Dia as FinDia,Isnull(StockTable.Print_DesignId,0) as DesignId,IsNull(Mas_Design.DesignDesc,'') as DesignDesc ,trs_del2.styleno FROM trs_del1 inner join trs_del2 on trs_del1.id=trs_del2.id INNER JOIN      StockTable ON trs_del2.StockID = StockTable.StockID INNER JOIN Mas_Fabric ON StockTable.FabID = Mas_Fabric.FabID INNER JOIN Mas_Count ON StockTable.CntID = Mas_Count.CountID INNER JOIN Mas_Dia ON StockTable.DiaID = Mas_Dia.DiaID LEFT OUTER JOIN Mas_Dia as Mas_Dia_1 ON StockTable.FinDiaID = Mas_Dia_1.DiaID INNER JOIN Mas_Uom ON Mas_Fabric.PriUomID = Mas_Uom.UomID LEFT OUTER JOIN Mas_Color ON StockTable.ColID = Mas_Color.ColID LEFT OUTER JOIN Mas_Design ON StockTable.Print_DesignId = Mas_Design.DesignID WHERE trs_del2.OrdId = @OrdId and stocktable.coycode = @Coycode and trs_del2.id=@FabDelID and trs_del2.stockid not in(select stockid from CurrentStock Where CurrentStock.OrdId = @ordid and GodId = @GodId group by stockid having  ISNULL(sum(CurrentStock.Kg),0)>0 or ISNULL(sum(CurrentStock.Mt),0)>0   ) group by Mas_Fabric.Fabdesc, Mas_Color.ColorDesc, Mas_Count.CountName, StockTable.LotNo,StockTable.Gsm, StockTable.ll, StockTable.GG,Mas_Dia.Dia, trs_del2.StockID, Mas_Uom.Uom,trs_del2.OrdId,StockTable.FinGsm,Mas_Dia_1.Dia ,Isnull(StockTable.Print_DesignId,0) ,IsNull(Mas_Design.DesignDesc,'')  ,trs_del2.styleno